CREATE TABLE IF NOT EXISTS "cps_mcp_access_log" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "api_key_id" bigint NULL,
    "member_id" bigint NULL,
    "actor_user_id" bigint NULL,
    "actor_user_type" varchar(16) NULL,
    "conversation_id" bigint NULL,
    "mcp_client_name" varchar(128) NULL,
    "invocation_source" varchar(32) NULL,
    "trace_id" varchar(64) NULL,
    "tool_name" varchar(64) NOT NULL,
    "request_params" text NULL,
    "response_data" text NULL,
    "status" tinyint NOT NULL DEFAULT 1,
    "error_message" varchar(512) NULL,
    "duration_ms" int NOT NULL DEFAULT 0,
    "client_ip" varchar(64) NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "cps_openapi_access_log" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "app_id" varchar(64) NULL,
    "request_method" varchar(16) NULL,
    "request_uri" varchar(255) NULL,
    "idempotency_key" varchar(128) NULL,
    "request_headers" text NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "failure_reason" varchar(128) NULL,
    "client_ip" varchar(64) NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_token_exchange_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "exchange_order_no" varchar(64) NOT NULL,
    "member_id" bigint NOT NULL,
    "source_system" varchar(32) NOT NULL,
    "source_asset" varchar(32) NOT NULL,
    "source_amount" decimal(10,2) NOT NULL,
    "target_asset" varchar(32) NOT NULL,
    "target_tokens" bigint NULL,
    "exchange_rate" decimal(12,4) NULL,
    "freeze_record_id" bigint NULL,
    "aitoken_exchange_order_id" varchar(64) NULL,
    "status" varchar(20) NOT NULL,
    "failure_reason" varchar(500) NULL,
    "idempotency_key" varchar(64) NOT NULL,
    "completed_at" datetime NULL,
    "retry_count" int NOT NULL DEFAULT 0,
    "next_retry_time" datetime NULL,
    "last_compensation_at" datetime NULL,
    "status_version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_exchange_tenant_order_no" UNIQUE ("tenant_id", "exchange_order_no"),
    CONSTRAINT "uk_exchange_tenant_idempotency" UNIQUE ("tenant_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_asset_ledger" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id" bigint NOT NULL,
    "source_system" varchar(32) NOT NULL,
    "business_type" varchar(32) NOT NULL,
    "business_id" varchar(128) NOT NULL,
    "order_id" bigint NULL,
    "platform_order_id" varchar(128) NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "available_change_cent" bigint NOT NULL DEFAULT 0,
    "frozen_change_cent" bigint NOT NULL DEFAULT 0,
    "debt_change_cent" bigint NOT NULL DEFAULT 0,
    "available_before_cent" bigint NOT NULL DEFAULT 0,
    "available_after_cent" bigint NOT NULL DEFAULT 0,
    "frozen_before_cent" bigint NOT NULL DEFAULT 0,
    "frozen_after_cent" bigint NOT NULL DEFAULT 0,
    "debt_before_cent" bigint NOT NULL DEFAULT 0,
    "debt_after_cent" bigint NOT NULL DEFAULT 0,
    "operator_type" varchar(16) NOT NULL,
    "operator_id" varchar(64) NULL,
    "reason" varchar(512) NOT NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_asset_ledger_tenant_idem" UNIQUE ("tenant_id", "business_type", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_order" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "platform_code" varchar(32) NOT NULL,
    "platform_order_id" varchar(128) NOT NULL,
    "order_status" varchar(32) NOT NULL,
    "last_sync_result" varchar(32) NULL,
    "raw_platform_status_summary" varchar(512) NULL,
    "status_version" int NOT NULL DEFAULT 0,
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) NULL DEFAULT '',
    "updater" varchar(64) NULL DEFAULT '',
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_order_tenant_platform_order" UNIQUE
        ("tenant_id", "platform_code", "platform_order_id")
);

CREATE TABLE IF NOT EXISTS "cps_order_status_event" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NULL,
    "platform_code" varchar(32) NOT NULL,
    "platform_order_id" varchar(128) NOT NULL,
    "source_type" varchar(32) NOT NULL,
    "source_batch_no" varchar(128) NULL,
    "raw_status" varchar(64) NULL,
    "raw_status_summary" varchar(512) NULL,
    "previous_status" varchar(32) NULL,
    "mapped_status" varchar(32) NOT NULL,
    "current_status" varchar(32) NOT NULL,
    "event_time" datetime NOT NULL,
    "status_version" int NOT NULL DEFAULT 0,
    "downgrade_rejected" bit NOT NULL DEFAULT FALSE,
    "reject_reason" varchar(512) NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "cps_order_attribution_log" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "order_id" bigint NULL,
    "platform_code" varchar(32) NOT NULL,
    "platform_order_id" varchar(128) NOT NULL,
    "candidate_member_id" bigint NULL,
    "attributed_member_id" bigint NULL,
    "attribution_source" varchar(32) NULL,
    "binding_type" varchar(32) NULL,
    "binding_id" varchar(128) NULL,
    "action" varchar(32) NOT NULL,
    "result" varchar(16) NOT NULL,
    "reject_reason" varchar(512) NULL,
    "operator_type" varchar(32) NOT NULL,
    "operator_id" varchar(128) NULL,
    "idempotency_key" varchar(128) NULL,
    "review_status" varchar(32) NULL,
    "review_audit_note" varchar(500) NULL,
    "review_operator_id" bigint NULL,
    "review_time" datetime NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_attribution_log_idempotency" UNIQUE ("tenant_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_order_sync_failure" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "platform_code" varchar(32) NOT NULL,
    "vendor_code" varchar(64) NOT NULL,
    "order_scene" int NOT NULL DEFAULT 0,
    "query_type" varchar(16) NOT NULL,
    "pagination_mode" varchar(16) NULL,
    "page_no" int NULL,
    "next_cursor" varchar(255) NULL,
    "sync_batch_no" varchar(255) NULL,
    "failure_stage" varchar(32) NOT NULL,
    "request_snapshot" varchar(1000) NULL,
    "raw_summary" varchar(2000) NULL,
    "failure_reason" varchar(1000) NULL,
    "status" varchar(16) NOT NULL,
    "retry_count" int NOT NULL DEFAULT 0,
    "max_retry_count" int NOT NULL DEFAULT 3,
    "next_retry_time" datetime NULL,
    "last_replay_time" datetime NULL,
    "replay_operator_id" bigint NULL,
    "replay_audit_note" varchar(500) NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_sync_failure_idempotency" UNIQUE ("tenant_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_platform_bill_row" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "platform_code" varchar(32) NOT NULL,
    "vendor_code" varchar(64) NULL,
    "bill_batch_no" varchar(128) NOT NULL,
    "platform_order_id" varchar(128) NOT NULL,
    "parent_order_id" varchar(128) NULL,
    "bill_status" varchar(64) NULL,
    "commission_amount" decimal(18,2) NULL,
    "refund_amount" decimal(18,2) NULL,
    "order_time" datetime NULL,
    "settle_time" datetime NULL,
    "refund_time" datetime NULL,
    "source_file_name" varchar(255) NULL,
    "raw_summary" varchar(2000) NULL,
    "idempotency_key" varchar(128) NOT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_platform_bill_row_idempotency" UNIQUE ("tenant_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_platform_bill_diff" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "bill_row_id" bigint NULL,
    "order_id" bigint NULL,
    "platform_code" varchar(32) NOT NULL,
    "vendor_code" varchar(64) NULL,
    "bill_batch_no" varchar(128) NOT NULL,
    "platform_order_id" varchar(128) NOT NULL,
    "diff_type" varchar(32) NOT NULL,
    "diff_status" varchar(32) NOT NULL,
    "diff_summary" varchar(512) NULL,
    "order_commission_amount" decimal(18,2) NULL,
    "bill_commission_amount" decimal(18,2) NULL,
    "bill_refund_amount" decimal(18,2) NULL,
    "order_status" varchar(32) NULL,
    "bill_status" varchar(64) NULL,
    "order_settle_time" datetime NULL,
    "bill_settle_time" datetime NULL,
    "handle_conclusion" varchar(64) NULL,
    "handle_audit_note" varchar(500) NULL,
    "handle_operator_id" bigint NULL,
    "handle_time" datetime NULL,
    "idempotency_key" varchar(160) NOT NULL,
    "version" int NOT NULL DEFAULT 0,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_platform_bill_diff_idempotency" UNIQUE ("tenant_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_account" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id" bigint NOT NULL,
    "total_rebate" decimal(18,2) NOT NULL DEFAULT 0,
    "available_balance" decimal(18,2) NULL DEFAULT 0,
    "frozen_balance" decimal(18,2) NULL DEFAULT 0,
    "debt_balance" decimal(18,2) NULL DEFAULT 0,
    "withdrawn_amount" decimal(18,2) NOT NULL DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 1,
    "version" int NOT NULL DEFAULT 0,
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) NULL DEFAULT '',
    "updater" varchar(64) NULL DEFAULT '',
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_account_tenant_member" UNIQUE ("tenant_id", "member_id")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id" bigint NOT NULL,
    "order_id" bigint NOT NULL,
    "rebate_type" varchar(32) NOT NULL,
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) NULL DEFAULT '',
    "updater" varchar(64) NULL DEFAULT '',
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_rebate_tenant_order_type" UNIQUE ("tenant_id", "order_id", "rebate_type")
);

CREATE TABLE IF NOT EXISTS "cps_freeze_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id" bigint NOT NULL,
    "order_id" bigint NULL,
    "platform_order_id" varchar(64) NULL,
    "business_type" varchar(32) NULL,
    "business_id" varchar(64) NULL,
    "idempotency_key" varchar(64) NULL,
    "freeze_amount" decimal(18,2) NOT NULL DEFAULT 0,
    "amount_cent" bigint NULL,
    "freeze_config_id" bigint NULL,
    "freeze_days_snapshot" int NULL,
    "eligible_time" datetime NULL,
    "unfreeze_time" datetime NULL,
    "actual_unfreeze_time" datetime NULL,
    "manual_unfreeze_reason" varchar(512) NULL,
    "manual_unfreeze_operator_id" varchar(64) NULL,
    "status" varchar(32) NOT NULL,
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "creator" varchar(64) NULL DEFAULT '',
    "updater" varchar(64) NULL DEFAULT '',
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_freeze_tenant_business_idem"
        UNIQUE ("tenant_id", "business_type", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_withdraw" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id" bigint NOT NULL,
    "withdraw_no" varchar(64) NOT NULL,
    "withdraw_type" varchar(32) NOT NULL,
    "withdraw_account" varchar(128) NOT NULL,
    "withdraw_account_name" varchar(64) NULL,
    "amount" decimal(18,2) NOT NULL,
    "amount_cent" bigint NOT NULL,
    "fee_amount" decimal(18,2) NOT NULL DEFAULT 0,
    "actual_amount" decimal(18,2) NOT NULL,
    "status" varchar(32) NOT NULL,
    "audit_user_id" bigint NULL,
    "audit_time" datetime NULL,
    "review_note" varchar(512) NULL,
    "transaction_no" varchar(64) NULL,
    "transfer_status" varchar(32) NULL,
    "transfer_time" datetime NULL,
    "transfer_error" varchar(512) NULL,
    "freeze_record_id" bigint NULL,
    "idempotency_key" varchar(64) NOT NULL,
    "status_version" int NOT NULL DEFAULT 0,
    "pay_transfer_id" bigint NULL,
    "transfer_channel_code" varchar(32) NULL,
    "retry_count" int NOT NULL DEFAULT 0,
    "next_retry_time" datetime NULL,
    "last_attempt_time" datetime NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_withdraw_tenant_idempotency" UNIQUE ("tenant_id", "idempotency_key")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_asset_migration_check" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "batch_no" varchar(64) NOT NULL,
    "tenant_id" bigint NOT NULL,
    "duplicate_account_count" bigint NOT NULL DEFAULT 0,
    "duplicate_order_count" bigint NOT NULL DEFAULT 0,
    "duplicate_rebate_record_count" bigint NOT NULL DEFAULT 0,
    "duplicate_ledger_idempotency_count" bigint NOT NULL DEFAULT 0,
    "duplicate_freeze_idempotency_count" bigint NOT NULL DEFAULT 0,
    "account_ledger_mismatch_count" bigint NOT NULL DEFAULT 0,
    "freeze_account_mismatch_count" bigint NOT NULL DEFAULT 0,
    "missing_opening_balance_count" bigint NOT NULL DEFAULT 0,
    "orphan_ledger_count" bigint NOT NULL DEFAULT 0,
    "orphan_active_freeze_count" bigint NOT NULL DEFAULT 0,
    "ready" bit NOT NULL DEFAULT FALSE,
    "operator_id" varchar(64) NOT NULL,
    "executed_at" datetime NOT NULL,
    "summary" varchar(512) NOT NULL,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_migration_check_tenant_batch" UNIQUE ("tenant_id", "batch_no")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_asset_policy" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "v2_enabled" bit NOT NULL DEFAULT FALSE,
    "migration_ready" bit NOT NULL DEFAULT FALSE,
    "latest_ready_check_batch_no" varchar(64) NULL,
    "ready_check_time" datetime NULL,
    "read_only" bit NOT NULL DEFAULT FALSE,
    "large_debt_threshold_cent" bigint NOT NULL DEFAULT 10000,
    "reminder_interval_days" int NOT NULL DEFAULT 7,
    "normal_reminder_days" int NOT NULL DEFAULT 30,
    "large_reminder_days" int NOT NULL DEFAULT 180,
    "sms_interval_days" int NOT NULL DEFAULT 30,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_asset_policy_tenant" UNIQUE ("tenant_id")
);

CREATE TABLE IF NOT EXISTS "cps_platform" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "platform_code" varchar(32) NOT NULL,
    "platform_name" varchar(64) NOT NULL,
    "platform_logo" varchar(255) NULL,
    "default_adzone_id" varchar(128) NULL,
    "platform_service_rate" decimal(10,4) NULL DEFAULT 0,
    "sort" int NULL DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 1,
    "extra_config" text NULL,
    "remark" varchar(512) NULL,
    "active_vendor_code" varchar(32) NULL,
    "supported_vendors" varchar(256) NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "active_unique_key" varchar(128) GENERATED ALWAYS AS (
        CASE WHEN "deleted" = FALSE
             THEN CONCAT(CAST("tenant_id" AS varchar), ':', "platform_code")
             ELSE NULL END
    ),
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_cps_platform_active" UNIQUE ("active_unique_key")
);

CREATE TABLE IF NOT EXISTS "cps_api_vendor" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "vendor_code" varchar(32) NOT NULL,
    "vendor_name" varchar(64) NOT NULL,
    "vendor_type" varchar(16) NOT NULL,
    "platform_code" varchar(32) NOT NULL,
    "app_key" varchar(128) NOT NULL,
    "app_secret" varchar(256) NOT NULL,
    "api_base_url" varchar(256) NOT NULL,
    "auth_token" varchar(512) NULL,
    "default_adzone_id" varchar(128) NULL,
    "extra_config" text NULL,
    "priority" int NOT NULL DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 1,
    "remark" varchar(256) NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_cps_api_vendor_tenant" UNIQUE
        ("tenant_id", "vendor_code", "platform_code", "deleted")
);

CREATE TABLE IF NOT EXISTS "cps_adzone" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "platform_code" varchar(32) NOT NULL,
    "adzone_id" varchar(128) NOT NULL,
    "adzone_name" varchar(128) NULL,
    "adzone_type" varchar(32) NULL DEFAULT 'general',
    "relation_type" varchar(32) NULL,
    "relation_id" bigint NULL,
    "external_relation_id" varchar(128) NULL,
    "external_special_id" varchar(128) NULL,
    "is_default" tinyint NOT NULL DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 1,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "active_unique_key" varchar(256) GENERATED ALWAYS AS (
        CASE WHEN "deleted" = FALSE
             THEN CONCAT(CAST("tenant_id" AS varchar), ':', "platform_code", ':', "adzone_id")
             ELSE NULL END
    ),
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_cps_adzone_active" UNIQUE ("active_unique_key")
);

CREATE TABLE IF NOT EXISTS "cps_rebate_config" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "member_id" bigint NULL,
    "member_level_id" bigint NULL,
    "platform_code" varchar(32) NULL,
    "rebate_rate" decimal(10,4) NOT NULL,
    "max_rebate_amount" decimal(10,2) NULL DEFAULT 0,
    "min_rebate_amount" decimal(10,2) NULL DEFAULT 0,
    "status" tinyint NOT NULL DEFAULT 1,
    "priority" int NOT NULL DEFAULT 0,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "cps_platform_onboarding_draft" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "platform_code" varchar(32) NOT NULL,
    "mode" varchar(16) NOT NULL,
    "payload_ciphertext" text NOT NULL,
    "draft_version" int NOT NULL DEFAULT 1,
    "config_fingerprint" varchar(64) NULL,
    "validated_fingerprint" varchar(64) NULL,
    "status" varchar(16) NOT NULL DEFAULT 'DRAFT',
    "check_summary" text NULL,
    "validated_at" datetime NULL,
    "published_at" datetime NULL,
    "creator" varchar(64) NULL DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) NULL DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "active_unique_key" varchar(128) GENERATED ALWAYS AS (
        CASE WHEN "deleted" = FALSE
             THEN CONCAT(CAST("tenant_id" AS varchar), ':', "platform_code")
             ELSE NULL END
    ),
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_cps_platform_onboarding_draft_active" UNIQUE ("active_unique_key")
);
